CREATE TABLE users (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, approved BOOLEAN NOT NULL DEFAULT TRUE, roll_number VARCHAR(80), faculty_id VARCHAR(80), branch VARCHAR(255), batch_year INTEGER, designation VARCHAR(255), cabin_location VARCHAR(255), department VARCHAR(255));
CREATE TABLE classrooms (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(255), building VARCHAR(255), floor VARCHAR(100), capacity INTEGER, amenities TEXT, directions TEXT, description TEXT, demonstration_data BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE assignments (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(255), category VARCHAR(100), due_date DATE, completed BOOLEAN NOT NULL DEFAULT FALSE); CREATE INDEX assignments_owner_idx ON assignments(owner_id);
CREATE TABLE attendance_records (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, student_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_code VARCHAR(80), course_name VARCHAR(255), attended_classes INTEGER NOT NULL, total_classes INTEGER NOT NULL, UNIQUE(student_id,course_code));
CREATE TABLE academic_events (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, title VARCHAR(255), event_date DATE, category VARCHAR(100), description TEXT, demonstration_data BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE resources (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, title VARCHAR(255), subject VARCHAR(255), resource_type VARCHAR(100), description TEXT, external_url TEXT, demonstration_data BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE consultation_slots (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, faculty_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, slot_date DATE, start_time TIME, end_time TIME, available BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(faculty_id,slot_date,start_time));
CREATE TABLE consultation_requests (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, student_id UUID NOT NULL REFERENCES users(id), faculty_id UUID NOT NULL REFERENCES users(id), slot_id UUID NOT NULL UNIQUE REFERENCES consultation_slots(id), status VARCHAR(20) NOT NULL, description VARCHAR(1200)); CREATE INDEX requests_student_idx ON consultation_requests(student_id); CREATE INDEX requests_faculty_idx ON consultation_requests(faculty_id);
CREATE TABLE class_schedules (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ, owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_code VARCHAR(80), course_name VARCHAR(255), weekday VARCHAR(20), start_time TIME, end_time TIME, classroom_id UUID REFERENCES classrooms(id));
